const current = REQUESTS.find((r) => r.id === selected)

<Page
      archetype="worklist"
      shape="list-detail"
      title="Approvals"
      detail={current
        ? <Card><CardTitle>{current.title}</CardTitle><p>{current.owner}</p></Card>: <EmptyState as="h2" surface="card" icon="list_alt" title="Nothing selected" />}
      footerBar={<Button variant="primary" disabled={!current}>Approve</Button>}
    >

      <Card flush>
        {REQUESTS.map((r) => (
          <ListItem key={r.id} onClick={() => setSelected(r.id)}>{r.title}</ListItem>
        ))}
      </Card>
